import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('CurrencyListPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
      CurrencyModel(
        id: '2',
        nominal: 1,
        name: 'Евро',
        symbol: 'EUR',
        value: 92.7440,
        previousValue: 92.2,
      ),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('USD'), findsOneWidget);
      expect(find.text('EUR'), findsOneWidget);
      expect(find.text('JPY'), findsNothing);
      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
    });

    testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should show load-more button when hasMore is true', (WidgetTester tester) async {
      final extraItems = [
        CurrencyModel(
          id: '3',
          nominal: 1,
          name: 'Иена',
          symbol: 'JPY',
          value: 0.5964,
          previousValue: 0.6001,
        ),
      ];

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (invocation) async {
          final request = invocation.argAt<CurrencyPageRequest>(0);
          if (request!.page == 0) {
            return CurrencyPage(items: currencyItems, page: 0, hasMore: true);
          } else {
            return CurrencyPage(items: extraItems, page: 1, hasMore: false);
          }
        },
      );

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      // Кнопка «Показать ещё» должна быть видна
      expect(find.text('Показать ещё'), findsOneWidget);
      // Должно быть 2 элемента (первая страница)
      expect(find.byType(CurrencyCard), findsNWidgets(2));

      // Нажимаем кнопку
      await tester.tap(find.text('Показать ещё'));
      await tester.pumpAndSettle();

      // Теперь должно быть 3 элемента (догрузили вторую страницу)
      expect(find.byType(CurrencyCard), findsNWidgets(3));
    });

    testWidgets('should keep search filter after loading more items', (WidgetTester tester) async {
      final extraItems = [
        CurrencyModel(
          id: '3',
          nominal: 1,
          name: 'Иена',
          symbol: 'JPY',
          value: 0.5964,
          previousValue: 0.6001,
        ),
      ];

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (invocation) async {
          final request = invocation.argAt<CurrencyPageRequest>(0);
          if (request!.page == 0) {
            return CurrencyPage(items: currencyItems, page: 0, hasMore: true);
          } else {
            return CurrencyPage(items: extraItems, page: 1, hasMore: false);
          }
        },
      );

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      // Введём поиск по 'USD' — должен остаться только один элемент
      await tester.enterText(find.byType(TextField), 'USD');
      await tester.pump();
      expect(find.byType(CurrencyCard), findsOneWidget);

      // Нажимаем кнопку «Показать ещё»
      await tester.tap(find.text('Показать ещё'));
      await tester.pumpAndSettle();

      // Фильтр должен примениться и к догруженным элементам — USD по-прежнему один
      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should not show load-more button when hasMore is false', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Показать ещё'), findsNothing);
    });
  });
}
