      await tester.enterText(find.byType(TextField), 'USD');
      await tester.pump();
      expect(find.byType(CurrencyCard), findsOneWidget);

      // Нажимаем кнопку «Показать ещё»
      await tester.tap(find.text('Показать ещё'));
      await tester.pumpAndSettle();

      // Фильтр должен примениться и к догруженным элементам — USD по-прежнему один
      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should not show load-more button when hasMore is false', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Показать ещё'), findsNothing);
    });
  });
}

